}
function hgSeasonTitle(name){
  var raw = String(name == null ? '' : name);
  var s = raw.split('\n').join('').trim();
  /* 只认「第N季」（任意位置）或「N季」结尾（站点有「…之无灵证道41季」这种不带「第」的写法）；
     中文数字的裸「N季」不认，免得把《人间四季》这类剧名当成第 4 季。 */
  var m = s.match(/第\s*([0-9]{1,3}|[一二三四五六七八九十]{1,3})\s*季/)
       || s.match(/([0-9]{1,3})\s*季\s*$/);
  if (!m) return raw;
  var base = s
    .replace(/第\s*(?:[0-9]{1,3}|[一二三四五六七八九十]{1,3})\s*季/g, '')
    .replace(/[0-9]{1,3}\s*季\s*$/, '')
    .replace(/[：:·・、,，\-–—_]+$/, '')
    .trim();
  if (!base) return raw;
  return base.substring(0, 4) + '第' + hgSnStr(m[1]) + '季';
}
function hgCards(d, list, isRank){
  for (var i = 0; i < list.length; i++) {
    var it = list[i] || {};
    var vd = it.video_data || {};                 /* 搜索结果的剧集数据包在 video_data 里 */
    var sid = it.series_id || it.seriesId || it.id || vd.series_id || '';
    if (!sid) continue;
    var cover = it.series_cover || it.cover || it.pic || vd.series_cover || '';
    var nm = it.series_name || it.title || it.name || vd.series_title || '';
    var nmS = hgSeasonTitle(nm);                  /* v35：含季号时显示「前四个字 + 第N季」 */
    var desc = isRank
      ? ((it.rank ? ('No.' + it.rank + '  ') : '') + (it.heatText || '') + (it.scoreText ? ('  ' + it.scoreText) : ''))
      : ((it.episode_right_text || vd.episode_right_text || '') + '\n' +
         String(it.series_intro || it.description || vd.series_intro || '').substring(0, 40));
    d.push({
      title: nmS,
      img: cover + '@Referer=' + HG_SITE,
      desc: String(desc || '').substring(0, 120),
      url: 'hiker://page/ep',
      extra: { url: HG_SITE + '/detail?series_id=' + sid },
      col_type: 'movie_3'
    });
  }
}

/* 跨季连播：剧名里含「第*季」（* 可阿拉伯数字或中文数字）时，在详情页渲染阶段查同剧
   的下一季，并把「下一季第1集」追加到选集列表末尾 —— 海阔播放器按详情页选集顺序连播，
   播完本季最后一集就会顺延到下一季第1集。
   查询结果按「剧名(去季号)+季号」做 6 小时文件缓存，避免每次进详情页都发请求。 */
var HGS_SITE = 'https://hongguoduanju.com';
var HGS_HDR = { 'Referer': HGS_SITE, 'User-Agent': 'Googlebot' };
/* 跨季结果缓存的格式版本：改动解析逻辑时把这个数加一，避免旧版本写坏的结果被读到 */
var HGS_CACHE_V = 13;                  /* v20：缓存条目新增 idx/cover/intro（重名判重与序号标注用），版本号 +1 */
var HGS_REQ  = 0;                      /* 本次整合发出的站点请求数（诊断用，落 hgs_timing.txt） */
var HGS_CONC_TEST = false;             /* 真机并发自测开关（默认关；诊断时临时置 true） */
/* v19：hgsSlowTip（「剧集整合中,请稍候」2 秒慢提示）与其开关 HGS_DONE 已删除 ——
   进入详情页不再有任何同步网络等待（有缓存直接渲染；首次直接用页面给的当前季），
   该提示没有存在必要；补齐过程统一由「补全所有季中 / 补全结束」两条 toast 播报。 */
var HGS_CN = { '零':0,'一':1,'二':2,'两':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9 };
function hgsCn2Num(s){
  s = String(s||'').replace(/[第季\s]/g,'');
  if (/^\d+$/.test(s)) return parseInt(s,10);
  if (s.indexOf('十') >= 0) {
    var p = s.split('十');
    var hi = p[0] ? (HGS_CN[p[0]]||0) : 1;
    var lo = p[1] ? (HGS_CN[p[1]]||0) : 0;
    return hi*10 + lo;
  }
  return HGS_CN[s] || 0;
}
function hgsSeasonNum(name){
  var s = String(name||'');
  /* v20：站点存在「谁说没灵根不能修仙的？之无灵证道41季」这种**不带「第」字**的写法，
     旧正则只认「第N季」，会把 40/41 季误判成第 1 季（于是被真首季挤掉、永远补不到）。
     现在先在**名称末尾**匹配「N季 / 第N季」，再退回「第N季出现在任意位置」的老规则。 */
  var m = s.match(/(?:第\s*)?([0-9]{1,3}|[一二三四五六七八九十]{1,3})\s*季\s*$/);
  if (m) return hgsCn2Num(m[1]);
  var m2 = s.match(/第\s*([0-9]{1,3}|[一二三四五六七八九十]{1,3})\s*季/);
  if (!m2) return 1;                 /* 剧名没写季号 = 隐式第一季 */
  return hgsCn2Num(m2[1]);
}
function hgsSeasonBase(name){
  var s = String(name||'');
  /* v19：剥掉季号后，再把尾部的分隔标点去掉 —— 站点存在「烬九州：第二十九季」这种
     带全角冒号的命名，旧写法会得到 base「烬九州：」，与首季「烬九州」不相等，
     导致同剧两套命名互相不认、补季补不到第 1 季。
     v20：① 先剥**名称末尾**的季号（含不带「第」字的「…41季」，否则 40/41 季永远匹配不上）；
          ② 再剥其它位置的「第N季」；③ 去掉尾部分隔标点；
          ④ 保护：剥完为空（剧名本身叫《四季》《两季》之类）就退回原名，避免误伤。
     只删「尾部的」分隔符，不动名称内部的冒号（「烬九州：征尘录」属另一部剧，仍不混入）。 */
  var t = s
    .replace(/(?:第\s*)?(?:[0-9]{1,3}|[一二三四五六七八九十]{1,3})\s*季\s*$/,'')
    .replace(/\s*第\s*(?:[0-9]{1,3}|[一二三四五六七八九十]{1,3})\s*季\s*/g,'')
    .replace(/[：:·・、,，\-–—_]+$/,'')
    .trim();
  return t ? t : s.trim();
}
/* v34：**合集族切分** —— `/player` 的 videoList 是「进入季所在合集 + 别的合集」的**拼接**，
   同一部剧的不同合集在标题命名上分族：如「持械入宋：第二季」（base 后紧跟全角冒号）、
   「持械入宋第二季」（无冒号）、裸名「持械入宋」，以及别的剧（「持械入宋：宣和铁骑」，
   已被剧名判据滤掉）。实测同一合集各季的海报/简介本来**互不相同**（封面 aHash 距离 0~14），
   跨合集 18~26，区间有重叠 —— 单靠图片/描述切不开，故用「命名族 + 列表前缀」做确定性切分
   （图片/描述相似度仍用于同名多 sid 条目之间的判重）。 */
function hgsFamKey(name, base){
  var s = String(name || '').split('\n').join('');
  if (s === base) return '';                 /* 裸剧名 = 隐式第 1 季，本身不带族标记 */
  if (s.indexOf(base) !== 0) return 'Z';
  var c0 = s.substring(base.length).charAt(0);
  return (c0 === '：' || c0 === ':') ? 'C' : 'P';
}
/* 取「本剧那一套合集」的**连续前缀**：
   · 族由**首个带季号的条目**决定（同一个合集的第 1 季常常就是裸剧名，如「烬九州」；
     另一个合集则可能叫「持械入宋：第一季」或「持械入宋」）；
   · 顺序遍历：同族/裸名照收；**一旦出现异族条目就截断**（名字不一致起就不是同一个合集了）；
   · 前缀跑完之后又冒出的裸剧名 = 另一个合集的第 1 季，同样截断。 */
function hgsFamRun(list, base){
  var out = [], fam = '', started = false, i, it, k, n = (list ? list.length : 0);
  for (i = 0; i < n; i++) {
    it = list[i] || {};
    if (hgsSeasonBase(it.name) !== base) continue;
    k = hgsFamKey(it.name, base);
    if (k === 'C' || k === 'P') { fam = k; break; }
  }
  if (!fam) return out;
  for (i = 0; i < n; i++) {
    it = list[i] || {};
    if (hgsSeasonBase(it.name) !== base) continue;
    k = hgsFamKey(it.name, base);
    if (k === '') {
      if (started) break;
      started = true; out.push(it); continue;
    }
    if (k !== fam) { if (started) break; continue; }
    started = true; out.push(it);
  }
  return out;
}
/* v34：播放页合集**偶发**返回「别的剧推荐列表」而不是本剧的季（实测同一 sid 6 次里 1 次），
   一次拿不到就重试，最多 tries 次，直到能切出本剧那一套合集为止。 */
function hgsPlayerFam(sid, base, tries){
  var n = tries || 3, k, lst, run;
  for (k = 0; k < n; k++) {
    try { lst = hgsPlayerSeasons(String(sid || '')); } catch (e) { lst = null; }
    if (!lst || !lst.length) continue;
    run = hgsFamRun(lst, base);
    if (run && run.length) return run;
  }
  return [];
}
function hgsSsrJSON(html){
  var raw = String(html||'');
  var i = raw.indexOf('_ROUTER_DATA');
  if (i < 0) return null;
  var eq = raw.indexOf('=', i), st = -1;
  for (var s = eq; s < raw.length; s++) { if (raw.charAt(s) === '{') { st = s; break; } }
  if (st < 0) return null;
  var dp = 0, ed = -1;
  for (var k = st; k < raw.length; k++) {
    var c = raw.charAt(k);
    if (c === '{') dp++; else if (c === '}') { dp--; if (dp === 0) { ed = k; break; } }
  }
  if (ed <= st) return null;
  try { return JSON.parse(raw.substring(st, ed + 1)); } catch (e) { return null; }
}
function hgsPick(ld, key){
  if (!ld) return null;
  for (var k in ld) { var w = (ld[k] || {}).content || ld[k]; if (w && w[key]) return w[key]; }
  return null;
}
/* 查同剧所有季：返回 [{season:季号, name:剧名, vids:[该季全部vid]}]（按季号升序）。
   - 剧名没有「第*季」时按第 1 季处理（剧名本身就是隐式第一季）
   - 站点搜索的 page 参数无效（1/2/3 页返回同一批 10 条），因此改用「多个关键词」
     扩展覆盖：先搜 base，发现不止一季再搜 base+第2季（统一阿拉伯季号），两次结果合并去重
     （实测 13 季的剧用这两次搜索即可全覆盖）
   - 当前季直接用页面已有数据补齐；结果按「剧名(去季号)」做 6 小时文件缓存 */
/* ---- 两段式整合的缓存与后台补齐 --------------------------------------
   缓存文件 hiker://files/cache/rg_seasons_<版本>_<剧名hash>.json，内容 {t, v, done}：
     done=0 → 只整合出「最小两季」（首屏秒开用），条目里附带后台线程在继续补
     done=1 → 全部季已整合好（下次进详情页直接全季秒开）
   每次进详情页都会自动做一次「增量检查」：① 最后一季有没有更新出新剧集
   ② 有没有出现新季（探 max+1 / max+2），命中就并进列表并回写缓存，无需任何按钮。 */
function hgsHash(base){
  var h = 0;
  for (var i = 0; i < base.length; i++) h = (h * 31 + base.charCodeAt(i)) % 100000007;
  return h;
}
function hgsCachePath(base){
  return 'hiker://files/cache/rg_seasons_' + HGS_CACHE_V + '_' + hgsHash(base) + '.json';
}
function hgsCachePick(base){
  if (!base) return null;
  try {
    var cs = readFile(hgsCachePath(base), 0);
    if (!cs) return null;
    var c = JSON.parse(String(cs));
    if (!c || (new Date().getTime() - (c.t || 0)) >= 6 * 3600 * 1000) return null;
    return { v: c.v || null, done: !!c.done };
  } catch (e) { return null; }
}
function hgsCacheWrite(base, v, done){
  try { saveFile(hgsCachePath(base), JSON.stringify({ t: new Date().getTime(), v: v, done: done ? 1 : 0 }), 0); } catch (e) {}
}

/* 补全锁：同一部剧同一时间只允许一个补全在跑（后台自动补齐 vs 用户点「补全所有季」），
   避免重复请求与两边并发写缓存。用文件时间戳做标记，10 分钟自动过期（防进程被杀后锁不释放）。 */
function hgsBgFlag(base){ return 'hiker://files/cache/rg_bg_' + hgsHash(base) + '.txt'; }
function hgsBgLock(base){
  try {
    var s = readFile(hgsBgFlag(base), 0);
    var t = s ? (parseInt(String(s), 10) || 0) : 0;
    if (t && (new Date().getTime() - t) < 10 * 60 * 1000) return false;   /* 还在跑 */
    saveFile(hgsBgFlag(base), String(new Date().getTime()), 0);
    return true;
  } catch (e) { return true; }
}
function hgsBgUnlock(base){ try { saveFile(hgsBgFlag(base), '0', 0); } catch (e) {} }
function hgsBgBusy(base){
  try {
    var s = readFile(hgsBgFlag(base), 0);
    var t = s ? (parseInt(String(s), 10) || 0) : 0;
    return !!(t && (new Date().getTime() - t) < 10 * 60 * 1000);
  } catch (e) { return false; }
}

/* v19：后台补齐（静默）—— 不再「全量重搜 + 逐季串行 detail + 每季一条 toast + sleep」，
   改为直接复用「补全所有季」按钮同款的批探算法 hgsBtnFill（一次把漏掉的季与后续季探完）。
   toast 只两条：开始「补全所有季中」、结束「补全结束」（用户明确要求）。
   不自动刷新页面：页面 setResult 后固化、同屏追加不了，用户点按钮即就地刷新显示。 */
function hgsBgFill(name, curSid, curVids, cover, intro){
  try {
    var base = hgsSeasonBase(name);
    if (!base) return false;
    if (!hgsBgLock(base)) return false;                    /* 已有补全在跑 → 不重复 */
    var th = new java.lang.Thread(function () {
      var _tb = new Date().getTime();
      try {
        try { toast('补全所有季中'); } catch (e) {}
        var n = 0;
        try {
          n = hgsBtnFill({ b:base, n:String(name || ''), s:String(curSid || ''),
                           c:String(cover || ''), i:String(intro || '') }, null);
        } catch (e) {}
        try {
          saveFile('hiker://files/cache/hgs_timing_bg.txt',
            '后台补全耗时=' + (new Date().getTime() - _tb) + 'ms  站点请求=' + HGS_REQ + '  新增季=' + n, 0);
        } catch (e) {}
        try { toast('补全结束'); } catch (e) {}
        /* v22：补到内容就刷新本页 —— 否则自动补全出来的季与集不会显示（页面 setResult 后固化）。
           只在 n>0（确实补到新季）时刷新，避免无变化时反复刷新；刷新后缓存已 done=1，
           页面重跑规则时不会再启动后台补齐，因此不会循环。 */
        try { if (n > 0) refreshPage(false); } catch (e) {}
      } catch (e) {}
      hgsBgUnlock(base);
    });
    th.start();
    return true;
  } catch (e) { return false; }
}

/* 拉某季的剧集列表（series_id → vid_list），失败返回 null */
function hgsDetailVids(sid){
  try {
    HGS_REQ++;
    var dh = String(fetch(HGS_SITE + '/detail?series_id=' + sid, { headers:HGS_HDR, timeout:15000 }) || '');
    var dj = hgsSsrJSON(dh);
    var sd = dj && hgsPick(dj.loaderData, 'seriesDetail');
    if (sd && sd.vid_list && sd.vid_list.length) return sd.vid_list;
  } catch (e) {}
  return null;
}
/* 并发取一批 URL 的原始文本：Rhino 里用 java.lang.Thread + CountDownLatch，结果写
   Java String[]（Java 数组元素写安全）；线程里只做「取原始文本」，JSON 解析留在
   主线程，尽量避开 Rhino 多线程作用域问题。并发不可用时自动回退串行。
   这是全部提速的底座：批量搜索与逐季 detail 都走它。 */
function hgsFetchRawAll(urls){
  var n = urls ? urls.length : 0;
  var out = [];
  for (var i0 = 0; i0 < n; i0++) out.push('');
  if (!n) return out;
  var BATCH = 5, ok = true;
  for (var b = 0; b < n && ok; b += BATCH) {
    var cnt = Math.min(BATCH, n - b);
    var arr, latch;
    try {
      arr = java.lang.reflect.Array.newInstance(java.lang.String, cnt);
      latch = new java.util.concurrent.CountDownLatch(cnt);
    } catch (e) { ok = false; break; }
    for (var i = 0; i < cnt; i++) {
      (function (slot, u) {
        var t = new java.lang.Thread(function () {
          try {
            HGS_REQ++;
            arr[slot] = String(fetch(u, { headers:HGS_HDR, timeout:20000 }) || '');
          } catch (e) { try { arr[slot] = ''; } catch (e2) {} }
          finally { try { latch.countDown(); } catch (e3) {} }
        });
        try { t.start(); } catch (e) { try { latch.countDown(); } catch (e2) {} }
      })(i, String(urls[b + i] || ''));
    }
    try { latch.await(25, java.util.concurrent.TimeUnit.SECONDS); } catch (e) {}
    for (var s = 0; s < cnt; s++) out[b + s] = String(arr[s] || '');
  }
  if (!ok) {
    for (var q = 0; q < n; q++) {
      if (out[q]) continue;
      try { HGS_REQ++; out[q] = String(fetch(urls[q], { headers:HGS_HDR, timeout:20000 }) || ''); } catch (e) {}
    }
  }
  return out;
}
/* 并发拉多季 detail（逐季串行 12 次 → 3 轮）：线程只取原始文本，解析在主线程做；
   拿不到的季再串行补一次，保证不漏季。 */
function hgsDetailVidsAll(sids){
  var n = sids ? sids.length : 0;
  var out = [];
  if (!n) return out;
  var urls = [];
  for (var i0 = 0; i0 < n; i0++) { urls.push(HGS_SITE + '/detail?series_id=' + String(sids[i0] || '')); out.push(null); }
  var raws = hgsFetchRawAll(urls);
  for (var s = 0; s < n; s++) {
    if (!raws[s]) continue;
    try {
