  var dbg = hgsFillDbg(base);
  function lg(s){
    try { saveFile(dbg, String(readFile(dbg, 0) || '') + '  ' + s + '\n', 0); } catch (e) {}
  }
  try { saveFile(dbg, '', 0); } catch (e) {}
