  if (hgsBgBusy(base)) {
    lg('bg busy -> 只刷新');
    try { refreshPage(false); } catch (e0) { lg('refreshPage ERR busy ' + e0); }
    return;
  }
  if (!hgsBgLock(base)) { lg('lock failed'); return; }        /* 抢锁失败（极少见） */
  try { saveFile(flag, '1 0', 0); } catch (e) {}
  try { toast('补全所有季中'); } catch (e) {}
  try {
    var th = new java.lang.Thread(function () {
      var n = 0, err = '';
      try { n = hgsBtnFill(p, lg); } catch (e) { err = String(e); }
      lg('fill done n=' + n + ' err=' + err);
      try { saveFile(flag, '2 ' + n, 0); } catch (e) {}
      try { toast('补全结束'); } catch (e) {}
      hgsBgUnlock(base);
      try { refreshPage(false); lg('refreshPage called'); }
      catch (e2) { lg('refreshPage ERR ' + e2); }
    });
    th.start();
    lg('thread started');
  } catch (e) {
    lg('thread FAIL ' + e);
    var n2 = 0;
    try { n2 = hgsBtnFill(p, lg); } catch (e2) {}
    try { saveFile(flag, '2 ' + n2, 0); } catch (e3) {}
    try { toast('补全结束'); } catch (e5) {}
    hgsBgUnlock(base);
    try { refreshPage(false); lg('refreshPage called (sync)'); } catch (e4) { lg('refreshPage ERR sync ' + e4); }
  }
}
